<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../config/config.php'; require_login(); if ((current_user()['role'] ?? '') !== 'admin') redirect('dashboard.php');
$message = ''; $allowed = ['csv'=>'text/csv','xlsx'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];
if ($_SERVER['REQUEST_METHOD'] === 'POST' && verify_csrf($_POST['csrf'] ?? null)) { $file = $_FILES['dataset'] ?? null; if (!$file || $file['error'] !== UPLOAD_ERR_OK) $message = 'Upload failed.'; elseif ($file['size'] > 10 * 1024 * 1024) $message = 'Maximum upload size is 10 MB.'; else { $extension = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION)); $mime = (new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']); if (!isset($allowed[$extension]) || ($extension === 'xlsx' && $mime !== $allowed['xlsx']) || ($extension === 'csv' && !in_array($mime, ['text/plain','text/csv','application/vnd.ms-excel'], true))) $message = 'Unsupported or invalid dataset file.'; else { if (!is_dir(UPLOAD_PATH . '/datasets')) mkdir(UPLOAD_PATH . '/datasets', 0750, true); $stored = bin2hex(random_bytes(16)) . '.' . $extension; $destination = UPLOAD_PATH . '/datasets/' . $stored; if (move_uploaded_file($file['tmp_name'], $destination)) { db()->prepare('INSERT INTO datasets(name,file_type,source_path,status) VALUES(?,?,?,?)')->execute([basename($file['name']),strtoupper($extension),$destination,'uploaded']); $message = 'Dataset uploaded and registered. Validate its columns before importing.'; } else $message = 'Could not store the uploaded file.'; } } }
$title = 'Upload dataset'; require __DIR__ . '/../includes/header.php'; ?><div class="container py-5"><div class="eyebrow">Admin · datasets</div><h1 class="section-title mb-4">Bring in a dataset carefully.</h1><?php if ($message): ?><div class="alert alert-info"><?= e($message) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="panel" style="max-width:620px"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label class="form-label">CSV or XLSX file</label><input class="form-control mb-3" type="file" name="dataset" accept=".csv,.xlsx" required><p class="small text-muted">Maximum 10 MB. Files receive generated names and are stored outside the public asset folders.</p><button class="btn btn-accent rounded-pill">Upload for validation</button></form></div><?php require __DIR__ . '/../includes/footer.php'; ?>